code.cpp:
class Solution {
public:
    int longestContinuousSubstring(string s) {
        int n = s.size();
        int maxLen = 1, cur = 1;
        for (int i = 1; i < n; i++) {
            if (s[i] == s[i-1] + 1) {
                cur++;
                if (cur > maxLen) maxLen = cur;
            } else {
                cur = 1;
            }
        }
        return maxLen;
    }
};
